local yeb,zeb,Aeb=ueb.forge_until(reb,seb)
web.sell=ueb.rack_count(reb)+(tonumber(Aeb)or 0)
web.coins=ueb.rack_value(reb)
local Beb=math.max(0,teb-xeb)
if veb.upgrade then
local Ceb
for Deb,Eeb in ipairs({obf[3721],obf[3722]})do
local Feb=tonumber(Eeb==obf[3721]and reb.f or reb.s)or 1
local Geb=Feb<ueb.max_level(Eeb)and ueb.get_level(Eeb,Feb+1)or nil
local Heb=Geb and tonumber(Geb.cost)or nil
if Heb and Heb<=Beb and(not Ceb or Heb<Ceb.cost)then
Ceb={kind=Eeb,cost=Heb,to=Feb+1}
end
end
if Ceb then
web.upgrade=Ceb
Beb=Beb-Ceb.cost
end
end
