function kb.feedPlan(Rnb)
local Snb=V.trait(Rnb)
local Tnb=Snb==obf[3808]and 1.5 or 1
local Unb=math.max(0,kb.xpFor(Rnb.unit_id,kb.cap(Rnb))-(tonumber(Rnb.xp)or 0))
local Vnb,Wnb,Xnb={},0,0
for Ynb,Znb in ipairs(kb.foodHeld())do
local _nb=Znb.xp*Tnb
local aob=math.min(Znb.n,math.floor((Unb-Wnb)/math.max(1,_nb)))
if aob>0 then
Vnb[Znb.id]=aob
Wnb=Wnb+aob*_nb
Xnb=Xnb+aob
end
end
return{feed=Vnb,planned=Wnb,n=Xnb}
end
function kb.run(bob)
