while U.now()-nob<4 and(tonumber((cob.collection:get_unit_by_uuid(bob.uuid)or dob).xp)or 0)<=iob do
task.wait(0.25)
end
local oob=cob.collection:get_unit_by_uuid(bob.uuid)or dob
local pob=(tonumber(oob.xp)or 0)-iob
if pob>0 then
local qob=kb.level(oob)
local rob=qob>kob and string.format(obf[3804],kob,qob)or string.format(obf[3805],kob)
cb.add(string.format(obf[3811],hob,bob.name),hob,obf[3812],string.format(obf[3813],U.fmt(pob),rob))
kb.note(string.format(obf[3814],bob.name,hob,U.fmt(pob),rob,math.abs(pob-gob)>gob*0.1 and string.format(obf[3815],U.fmt(gob))or obf[1555]))
else
kb.note(string.format(obf[3816],bob.name,tostring(lob and mob or obf[3212])))
F.backoff(obf[3802],600)
end
end
