local rvb=ovb..obf[2971]..kvb.uuid..(pvb and obf[3980]or obf[3981])..obf[3982]
local svb=P.trainSim[jvb.key]
if svb and svb.sig==rvb and not svb.pending and os.time()-(svb.at or 0)<6*3600 then
return svb
end
local tvb={sig=rvb,base=ovb,uuid=kvb.uuid,at=os.time(),ok=false,margin=qvb,pending=true}
P.trainSim[jvb.key]=tvb
