Ovb[Fvb[Nvb].i]=Bvb
local Pvb=gb.teamFrom(Ovb,wvb.map)
local Qvb=gb.run(wvb,Pvb,{hpMul=qvb,train=kvb.uuid})
if(Dvb and W.infTier(Qvb.wave)>=Evb)or(not Dvb and Qvb.won)then
local Rvb=gb.run(wvb,Pvb,{hpMul=1,train=kvb.uuid})
