tvb.ok=true
end
end
tvb.pending=nil
F.log(1,obf[3992],string.format(obf[3993],jvb.label,V.name(kvb.id),tvb.out and(obf[3994]..V.name(tvb.out))or obf[1555],tvb.ok and string.format(obf[3995],math.floor((ib.perRun(jvb.key,kvb.id)or 0)+0.5),kvb.what,tvb.minutes,tvb.ownMin)or tostring(tvb.why)))
F.saveSoon()
