gb.REINC_WAVES,gb.REINC_BOOST,gb.REINC_PUSH,gb.REINC_SELL,gb.REINC_LEFT,gb.SELL_BACK=30,6,0.5,0.6,10,0.25
function gb.reincLong(Ync)
