gb.INF_CAP=80
function gb.evaluate(Znc,_nc)
local aoc=gb.run(Znc,_nc,{hpMul=1})
local boc={won=aoc.won,wave=aoc.wave,minutes=aoc.t/60,aliveAt=aoc.aliveAt,total=Znc.total,at=os.time()}
if Znc.infinite and gb.unbound(Znc.ld)then
boc.p=1
boc.margin=aoc.won and string.format(obf[4635],Znc.total)or(aoc.timeout and Znc.timeLimit and string.format(obf[4636],math.floor(Znc.timeLimit/60+0.5),aoc.wave))or string.format(obf[4637],aoc.wave,aoc.t/60)
elseif aoc.won then
local coc=gb.run(Znc,_nc,{hpMul=1.3})
boc.p=coc.won and 0.92 or 0.7
boc.margin=coc.won and obf[4638]or obf[4639]
else
local doc=gb.run(Znc,_nc,{hpMul=0.75})
boc.p=doc.won and 0.25 or 0.05
boc.margin=doc.won and string.format(obf[4640],aoc.wave)or string.format(obf[4641],aoc.wave,Znc.total)
if not doc.won then
local eoc=gb.run(Znc,_nc,{hpMul=0.25})
if not eoc.won then
boc.p,boc.hopeless=0.005,true
boc.margin=string.format(obf[4642],aoc.wave,Znc.total)
end
end
end
return boc
end
gb.STYLE_RUNS=20
function gb.styleP(foc,goc)
local hoc=tonumber(foc and foc.p)or 0
if hoc<0.5 then
return hoc
end
goc=goc or((foc.zone or foc.style==obf[4578])and obf[4578]or obf[4643])
local ioc,joc=pcall(db.hiveStyle,goc)
if not(ioc and joc)then
return hoc
end
local koc=tonumber(joc.predWin)or 0
local loc=U.clamp((tonumber(joc.predWinWon)or 0)/math.max(1,koc),0,1)
local moc=koc/(koc+gb.STYLE_RUNS)
return hoc*(1-moc*(1-loc))
end
function gb.levelTag(noc)
