return obf[2892]
end
if noc._gamemode==obf[2689]or noc._infinite_tower_floor then
return obf[4644]..tostring(noc._infinite_tower_floor or noc.floor_num or obf[2892])
end
return tostring(noc.id or obf[2892])..(mb.is(noc.id)and(obf[3088]..tostring(noc.map))or obf[1555])
end
function gb.trust(ooc,poc)
local qoc=ooc.cal or{}
if type(qoc.alive)~=obf[2639]or qoc.teamSig~=gb.sig((function()
local roc={}
for soc,toc in ipairs(poc)do
table.insert(roc,toc.u)
end
return roc
end)())then
return nil
end
if ooc.key==obf[3389]and not qoc.aliveLvl then
return nil
end
if qoc.aliveLvl and ooc.ld and(ooc.ld.id or ooc.key==obf[3302])and qoc.aliveLvl~=gb.levelTag(ooc.ld)then
return nil
end
local uoc=gb.run(ooc,poc,{hpMul=1})
local voc,woc,xoc=0,0,0
for yoc=3,math.min(uoc.wave,tonumber(qoc.lastWave)or 99)do
local zoc=tonumber(qoc.alive[tostring(yoc)])
local Aoc=uoc.aliveAt[yoc]
if zoc and Aoc and zoc>0 then
voc=voc+zoc
woc=woc+Aoc
xoc=xoc+1
end
end
if xoc<2 or woc<=0 then
return nil
end
local Boc=voc/woc
return{ratio=Boc,ok=Boc>=0.75 and Boc<=1.33,waves=xoc}
end
gb.GROWN_LEVEL,gb.GROWN_MIN=50,6
function gb.grownKinds()
local Coc=N.session()
local Doc,Eoc={},0
for Foc,Goc in pairs(Coc.profile_data.collection.owned_units)do
local Hoc=Goc.unit_id
if not Doc[Hoc]and N.Units[Hoc]and not V.isFarm(Hoc)and V.rows(Hoc)and not V.hidden(Hoc)then
local Ioc,Joc=pcall(N.USC.calculate_level,Hoc,tonumber(Goc.xp)or 0)
if Ioc and(tonumber(Joc)or 0)>=gb.GROWN_LEVEL then
Doc[Hoc]=true
Eoc=Eoc+1
end
end
end
return Eoc
end
gb.EVO_KEEP=0.5
function gb.dropUnevolved(Koc,Loc)
local Moc={}
for Noc,Ooc in pairs(Koc)do
local Poc,Qoc=Loc(Noc),0
while Poc and Qoc<4 do
local Roc=Koc[Poc]
if Roc and(tonumber(Roc.sc)or 0)>=gb.EVO_KEEP*(tonumber(Ooc.sc)or 0)then
Moc[Noc]=Poc
break
end
Poc,Qoc=Loc(Poc),Qoc+1
end
end
for Soc in pairs(Moc)do
Koc[Soc]=nil
end
return Moc
end
function gb.pool(Toc,Uoc)
local Voc=N.session()
local Woc,Xoc={},{}
local Yoc=gb.grownKinds()>=gb.GROWN_MIN
for Zoc,_oc in pairs(Voc.profile_data.collection.owned_units)do
local apc=Voc.collection:get_unit_by_uuid(_oc.uuid)or _oc
local bpc,cpc=pcall(N.USC.calculate_level,apc.unit_id,tonumber(apc.xp)or 0)
local dpc=V.isFarm(apc.unit_id)or not Yoc or(bpc and(tonumber(cpc)or 0)>=gb.GROWN_LEVEL)
local epc=N.Units[apc.unit_id]and V.rows(apc.unit_id)and V.isFarm(apc.unit_id)and V.farm(apc,V.rows(apc.unit_id).max)<=0
if N.Units[apc.unit_id]and V.rows(apc.unit_id)and not V.hidden(apc.unit_id)and dpc and not epc then
local fpc=V.isFarm(apc.unit_id)
local gpc,hpc=pcall(fpc and function()
return V.farm(apc,V.rows(apc.unit_id).max)
end or V.score,apc,Toc)
hpc=(gpc and hpc or 0)*(fpc and 1 or V.skinMul(apc,Uoc and Uoc.skinSet)*V.eventMul(apc,Uoc and Uoc.ld))
local ipc=fpc and Xoc or Woc
if not ipc[apc.unit_id]or hpc>ipc[apc.unit_id].sc then
ipc[apc.unit_id]={u=apc,sc=hpc}
end
end
end
local function jpc(kpc)
local lpc=N.Units[kpc]
local mpc=type(lpc)==obf[2639]and type(lpc.evolve)==obf[2639]and lpc.evolve.evolve_unit or nil
return mpc~=kpc and mpc or nil
end
pcall(gb.dropUnevolved,Woc,jpc)
pcall(gb.dropUnevolved,Xoc,jpc)
local opc,ppc={},{}
for qpc,rpc in pairs(Woc)do
table.insert(opc,rpc)
end
for spc,tpc in pairs(Xoc)do
table.insert(ppc,tpc)
end
table.sort(opc,function(upc,vpc)
return upc.sc>vpc.sc
end)
table.sort(ppc,function(wpc,xpc)
return wpc.sc>xpc.sc
end)
local ypc={}
for zpc=1,math.min(10,#opc)do
table.insert(ypc,opc[zpc].u)
end
local Apc,Bpc={},{}
for Cpc=11,#opc do
local Dpc=V.rows(opc[Cpc].u.unit_id)
for Epc=0,Dpc.max do
if Dpc[Epc]and Dpc[Epc].atk and V.attackInfo(Dpc[Epc].atk,Dpc[Epc].range).dot>0 then
table.insert(Epc==0 and Apc or Bpc,opc[Cpc].u)
break
end
end
end
for Fpc=1,math.min(4,#Apc)do
table.insert(ypc,Apc[Fpc])
end
for Gpc=1,math.min(2,#Bpc)do
table.insert(ypc,Bpc[Gpc])
end
for Hpc=1,math.min(3,#ppc)do
table.insert(ypc,ppc[Hpc].u)
end
local Ipc={}
for Jpc=11,#opc do
local Kpc=V.rows(opc[Jpc].u.unit_id)[0]
local Lpc=Kpc and Kpc.atk and V.attackInfo(Kpc.atk,Kpc.range)
if Lpc and(Lpc.slowTime>0 or Lpc.stun>0)then
table.insert(Ipc,opc[Jpc].u)
end
end
for Mpc=1,math.min(3,#Ipc)do
table.insert(ypc,Ipc[Mpc])
end
for Npc=11,#opc do
local Opc=opc[Npc].u.unit_id
if V.allyBuff(Opc)or V.BLESS.by[Opc]or V.GALE[Opc]then
table.insert(ypc,opc[Npc].u)
end
end
if Uoc and(Uoc.shield or 0)>0 then
for Ppc=11,#opc do
if V.breaksShields(opc[Ppc].u.unit_id)then
table.insert(ypc,opc[Ppc].u)
end
end
end
if Uoc and(tonumber(Uoc.regen)or 0)>0 then
for Qpc=11,#opc do
local Rpc,Spc=pcall(V.bleeds,opc[Qpc].u.unit_id)
if Rpc and Spc and not V.breaksShields(opc[Qpc].u.unit_id)then
table.insert(ypc,opc[Qpc].u)
end
end
end
if Uoc and((Uoc.flyChance or 0)>0 or Uoc.mapFly or(Uoc.shield or 0)>0)then
local Tpc,Upc={},{}
for Vpc=11,#opc do
local Wpc=opc[Vpc].u
local Xpc=V.rows(Wpc.unit_id)[0]
if V.airFrom(Wpc.unit_id)==0 then
table.insert(Tpc,Wpc)
end
local Ypc,Zpc=tonumber(Xpc and Xpc.cd)or 0,tonumber((N.Units[Wpc.unit_id]or{}).cost)or 0
if Ypc>0 and Zpc>0 and V.range(Wpc,0)>=15 then
local _pc=V.attackInfo(Xpc.atk,Xpc.range)
table.insert(Upc,{u=Wpc,v=_pc.n*_pc.hits/Ypc/Zpc*math.min(6,V.cap(Wpc))})
end
end
table.sort(Upc,function(aqc,bqc)
return aqc.v>bqc.v
end)
for cqc=1,math.min(4,#Tpc)do
table.insert(ypc,Tpc[cqc])
end
for dqc=1,math.min(6,#Upc)do
table.insert(ypc,Upc[dqc].u)
end
end
local eqc,fqc={},{}
for gqc,hqc in ipairs(ypc)do
if not eqc[hqc]then
eqc[hqc]=true
table.insert(fqc,hqc)
end
end
fqc.rest={}
for iqc,jqc in ipairs(opc)do
if not eqc[jqc.u]then
table.insert(fqc.rest,jqc.u)
end
end
return fqc
end
function gb.objective(kqc)
if kqc.kscore then
return(tonumber(kqc.kills)or 0)+kqc.wave*0.01
end
return(kqc.won and 1000 or 0)+kqc.wave*10-(kqc.won and kqc.t/60 or((kqc.left or 1)*9-math.min(9,kqc.t/60)))
end
gb.LADDER={1,1.3,1.7,2.2,3,4,6,8,12,16,24}
function gb.cliff(lqc,mqc,nqc)
local oqc
for pqc,qqc in ipairs(gb.LADDER)do
oqc=gb.run(lqc,mqc,{hpMul=qqc,layout=nqc})
if not oqc.won then
return qqc,oqc
end
end
return gb.LADDER[#gb.LADDER],oqc
end
gb.TEAM_FASTER,gb.TEAM_FASTER_S=0.05,15
function gb.teamFaster(rqc,sqc,tqc)
if rqc.infinite or rqc.timeLimit or type(tqc)~=obf[2639]or not tqc.won or not tonumber(tqc.minutes)then
return nil
end
local uqc=gb.teamFrom(sqc,rqc.map)
local vqc=gb.run(rqc,uqc,{hpMul=1})
if not(vqc and vqc.won)then
return nil
end
local wqc=gb.run(rqc,uqc,{hpMul=1.3})
if not(wqc and wqc.won)then
return nil
end
local xqc,yqc=tonumber(tqc.minutes)*60,tonumber(vqc.t)or math.huge
if yqc<=xqc*(1-gb.TEAM_FASTER)and xqc-yqc>=gb.TEAM_FASTER_S then
return{mine=xqc,pick=yqc}
end
return nil
end
function gb.exam(zqc,Aqc)
local Bqc,Cqc,Dqc=gb.teamFrom(Aqc,zqc.map),0,0
for Eqc,Fqc in ipairs(gb.LADDER)do
local Gqc,Hqc=0,0
for Iqc,Jqc in ipairs({0.92,1,1.08})do
local Kqc=gb.run(zqc,Bqc,{hpMul=Fqc*Jqc})
if Kqc.won then
Gqc=Gqc+1
end
Hqc=Hqc+Kqc.wave
end
Cqc,Dqc=Cqc+Gqc,Hqc/3
task.wait()
if Gqc==0 then
break
end
end
return Cqc,Dqc
end
gb.ZONE_CLOSE,gb.ZONE_GAIN=1.3,20
function gb.zoneKey(Lqc)
return tostring(Lqc.key)..obf[2792]..tostring(Lqc.map)
end
function gb.zoneChoice(Mqc,Nqc,Oqc,Pqc)
if O.killZone==false or Mqc.zone or bb.forcedWay(Mqc)or(Mqc.infinite and gb.unbound(Mqc.ld))then
return false
end
local Qqc=P.zoneRec[gb.zoneKey(Mqc)]
local Rqc=Qqc and(Qqc.style==obf[4578]or(Qqc.style==nil and Qqc.zone==true))
if Qqc and Qqc.won then
return Rqc==true,Rqc and obf[4645]or nil
end
if Qqc and Rqc then
return false,obf[4646]
end
local Sqc=P.modes[Mqc.key]
local Tqc=Sqc and tonumber(Sqc.streak)or 0
if not Qqc and Sqc and(tonumber(Sqc.wins)or 0)>0 and Tqc==0 and Mqc.key~=obf[3389]and Mqc.key~=obf[3385]then
return false
end
local Uqc=Qqc~=nil or Tqc>0
local Vqc=Pqc and Oqc<=1 or(not Pqc and Oqc<=gb.ZONE_CLOSE)
if not(Uqc or Vqc)then
return false
end
local Wqc=table.clone(Mqc)
Wqc.zone=true
local function Xqc(Yqc)
local Zqc=0
for _qc,arc in ipairs({0.92,1,1.08})do
Zqc=Zqc+gb.objective(gb.run(Yqc,Nqc,{hpMul=Oqc*arc}))
end
return Zqc/3
end
local brc=Xqc(Wqc)-Xqc(Mqc)
if Uqc and brc> -gb.ZONE_GAIN then
return true,obf[4647],brc
end
if Vqc and brc>gb.ZONE_GAIN then
return true,string.format(obf[4648],Oqc),brc
end
return false,nil,brc
end
function gb.strength(crc,drc)
local erc,frc,grc,hrc,irc=gb.teamFrom(drc,crc.map),0,0,0,0
for jrc,krc in ipairs(gb.LADDER)do
local lrc,mrc=0,0
for nrc,orc in ipairs({0.92,1,1.08})do
local prc=gb.run(crc,erc,{hpMul=krc*orc})
if prc.won then
lrc=lrc+1
end
mrc=mrc+prc.wave
end
frc,irc=frc+lrc,mrc/3
if krc==1 then
grc,hrc=lrc,mrc/3
end
task.wait()
if lrc==0 then
break
end
end
