function jb.playLast()
local UHc=P.dg.playLast
return type(UHc)==obf[2639]and os.time()-(tonumber(UHc.at)or 0)<1800 and UHc or nil
end
function jb.missCounter(VHc,WHc,XHc)
if type(VHc)~=obf[2639]or(tonumber(VHc.regen)or 0)<=0 or(tonumber(VHc.shield)or 0)>0 then
return nil
end
local function YHc(ZHc)
local _Hc,aIc
for bIc,cIc in ipairs(ZHc or{})do
local dIc,eIc=pcall(V.bleeds,cIc.unit_id)
if dIc and eIc and(not aIc or eIc<aIc)then
_Hc,aIc=cIc.unit_id,eIc
end
end
return _Hc,aIc
end
local fIc=YHc(WHc)
local gIc,hIc=YHc(XHc)
if fIc or not gIc then
return nil
end
return string.format(obf[4877],tostring(math.floor(VHc.regen*1000+0.5)/10),V.name(gIc),hIc>0 and string.format(obf[4878],hIc)or obf[1555])
end
function jb.forced(iIc)
local jIc=P.dg.force
if type(jIc)==obf[2639]and type(jIc.uuids)==obf[2639]and jIc.seed==tostring(iIc.r._r)then
if os.time()-(tonumber(jIc.at)or 0)>3600 then
P.dg.force=nil
return nil
end
return jIc
end
local kIc=P.dg.forceRun
if type(kIc)~=obf[2639]or type(kIc.uuids)~=obf[2639]then
return nil
end
kIc.seeds=type(kIc.seeds)==obf[2639]and kIc.seeds or{}
local lIc=tostring(iIc.r._r)
local mIc,nIc=0,false
for oIc in pairs(kIc.seeds)do
mIc=mIc+1
if oIc==lIc then
nIc=true
end
end
if os.time()-(tonumber(kIc.at)or 0)>3*3600 or(not nIc and mIc>=(tonumber(kIc.rooms)or 5))then
P.dg.forceRun=nil
F.log(1,obf[4879],obf[4880])
return nil
end
kIc.seeds[lIc]=true
return kIc
end
function jb.startTeam(pIc,qIc,rIc,sIc)
P.startTeam={uuids=table.clone(pIc),must=true,own=sIc or nil,seed=tostring(qIc.r._r),why=rIc}
end
function jb.weakMatch(tIc,uIc)
local vIc,wIc=pcall(V.types,tIc)
if not vIc or type(wIc)~=obf[2639]then
return false
end
for xIc,yIc in pairs(wIc)do
local zIc=type(xIc)==obf[2640]and yIc or xIc
if uIc[zIc]then
return true
end
end
return false
end
function jb.fasterTeam(AIc,BIc,CIc,DIc,EIc)
local FIc=U.now()
local function GIc(HIc)
local IIc=gb.run(AIc,gb.teamFrom(HIc,AIc.map),{hpMul=1})
return IIc and IIc.won and tonumber(IIc.t)or nil
end
local JIc=GIc(BIc)
if not JIc then
return nil
end
local KIc={}
for LIc,MIc in ipairs(BIc)do
KIc[MIc.unit_id]=true
end
local NIc={}
for OIc,PIc in ipairs(CIc)do
if#NIc>=6 then
break
end
if not KIc[PIc.unit_id]and not V.isFarm(PIc.unit_id)and not V.allyBuff(PIc.unit_id)and jb.weakMatch(PIc.unit_id,DIc)then
KIc[PIc.unit_id]=true
table.insert(NIc,PIc)
end
end
if#NIc==0 then
return nil
end
local QIc,RIc,SIc=table.clone(BIc),JIc,{}
local TIc=gb.lockIds()
for UIc,VIc in ipairs(BIc)do
if U.now()-FIc>EIc then
break
end
if not TIc[VIc.unit_id]and not V.isFarm(VIc.unit_id)and not V.allyBuff(VIc.unit_id)and not jb.weakMatch(VIc.unit_id,DIc)then
local WIc,XIc
for YIc,ZIc in ipairs(NIc)do
if U.now()-FIc>EIc then
break
end
if not SIc[ZIc.uuid]then
local _Ic=table.clone(QIc)
_Ic[UIc]=ZIc
local aJc=GIc(_Ic)
if aJc and aJc<(XIc or RIc)then
WIc,XIc=ZIc,aJc
end
end
end
if WIc then
QIc[UIc]=WIc
SIc[WIc.uuid]=true
RIc=XIc
end
task.wait()
end
end
if RIc<JIc then
return QIc,JIc,RIc
end
return nil
end
function jb.lostSwap(bJc,cJc,dJc)
if dJc or type(bJc)~=obf[2639]or type(cJc)~=obf[2639]then
return false
end
return(bJc.lostHere or 0)>(cJc.lostHere or 0)and(cJc.score or 0)>(bJc.score or 0)and(cJc.wins or 0)>0
end
function jb.weakSlot(eJc)
local fJc,gJc
for hJc,iJc in ipairs(eJc or{})do
if not iJc.farm and not iJc.buff and not iJc.kept and(not gJc or(iJc.score or 0)<gJc)then
fJc,gJc=hJc,iJc.score or 0
end
end
return fJc
end
function jb.planTeam(jJc,kJc,lJc)
if not(O.sim and O.simTeams)or type(jJc.r._l)~=obf[2639]then
return
end
if jb.playLast()then
F.log(1,obf[4562],string.format(obf[4881],jJc.d))
return
end
local mJc=jb.forced(jJc)
if mJc then
if lJc then
F.log(1,obf[4562],string.format(obf[4882],jJc.d,tostring(mJc.label)))
if not ib.same(ib.team(),mJc.uuids)then
jb.startTeam(mJc.uuids,jJc,tostring(mJc.label))
end
return
end
F.log(1,obf[4562],string.format(obf[4883],jJc.d,tostring(mJc.label)))
ab.equipTeam(mJc.uuids,tostring(mJc.label))
task.wait(0.5)
return
end
if lJc and not O.autoTeam then
return
end
local nJc=P.simTeam.dg
if not lJc and O.autoTeam and nJc and nJc.better and not nJc.stale and nJc.seed==tostring(jJc.r._r)and os.time()-(tonumber(nJc.at)or 0)<300 then
ab.equipTeam(nJc.uuids,obf[4884]..jJc.d)
task.wait(0.5)
return
end
local oJc=jb.fx(kJc,jb.roomCurse(jJc.r))
local pJc={}
if lJc and type(P.savedTeam)==obf[2639]and#P.savedTeam>0 then
local qJc=N.session()
for rJc,sJc in ipairs(P.savedTeam)do
local tJc=qJc.collection:get_unit_by_uuid(sJc)
if tJc then
table.insert(pJc,tJc)
end
end
else
for uJc,vJc in ipairs(V.equipped())do
table.insert(pJc,vJc.u)
end
end
if#pJc==0 then
return
end
local wJc=jb.mod(jJc.r._l)
local xJc=gb.applyFx(gb.info(gb.slim(jJc.r._l),obf[3427],nil,wJc),oJc)
local yJc=jb.applyK(xJc,jJc.r._r)
if yJc>1 then
F.log(1,obf[4562],string.format(obf[4885],jJc.d,yJc))
end
F.status(obf[3837],obf[4886]..jJc.d)
gb.memoOn()
local zJc=jb.ways(xJc)
local AJc=type(P.dg.styles)==obf[2639]and P.dg.styles[tostring(jJc.r._r)]or nil
local function BJc(CJc,DJc)
local EJc=gb.sig(CJc)
local FJc=type(P.dg.teams)==obf[2639]and P.dg.teams[EJc]or{}
local GJc=type(P.dg.lost)==obf[2639]and P.dg.lost[tostring(jJc.r._r)]and P.dg.lost[tostring(jJc.r._r)][EJc]or 0
local HJc=type(P.dg.bailed)==obf[2639]and type(P.dg.bailed[tostring(jJc.r._r)])==obf[2639]and tonumber(P.dg.bailed[tostring(jJc.r._r)][EJc])or 0
GJc=GJc+HJc
local IJc,JJc,KJc,LJc=gb.strength(DJc.info,CJc)
local MJc=math.clamp((tonumber(FJc.w)or 0)-2*(tonumber(FJc.l)or 0),-6,3)
if jJc.d>=13 then
MJc=math.min(MJc,1)
end
MJc=MJc-3*GJc
local NJc=AJc and type(AJc.lost)==obf[2639]and AJc.lost[DJc.style]or nil
if type(NJc)==obf[2639]and NJc.sig==EJc then
MJc=MJc-3
end
return{score=IJc+MJc,wins=IJc,atOne=JJc,reach=KJc,far=LJc,lostHere=GJc,left=HJc,w=tonumber(FJc.w)or 0,l=tonumber(FJc.l)or 0,style=DJc.style}
end
local function OJc(PJc)
for QJc,RJc in ipairs(zJc)do
if RJc.style==PJc then
return RJc
end
end
return zJc[2]
end
local function SJc(TJc,UJc)
return not UJc or TJc.score>UJc.score or(TJc.score==UJc.score and(TJc.far or 0)>(UJc.far or 0))
end
local function VJc(WJc)
local XJc
for YJc,ZJc in ipairs(zJc)do
local _Jc=BJc(WJc,ZJc)
if SJc(_Jc,XJc)then
XJc=_Jc
end
task.wait()
end
return XJc
end
local aKc=VJc(pJc)
if O.dgFaster and aKc.wins>=3* #gb.LADDER and aKc.lostHere==0 and wJc and next(wJc.weak)~=nil then
local bKc=OJc(aKc.style)
local cKc,dKc,eKc,fKc=pcall(jb.fasterTeam,bKc.info,pJc,gb.pool(wJc,xJc),wJc.weak,8)
if not cKc then
F.log(1,obf[2648],obf[4887]..tostring(dKc))
end
if cKc and dKc and fKc<=eKc*(1-gb.TEAM_FASTER)and eKc-fKc>=gb.TEAM_FASTER_S then
local gKc=BJc(dKc,bKc)
if gKc.wins>=aKc.wins and gKc.lostHere==0 then
gb.memo=nil
local hKc,iKc={},{}
for jKc,kKc in ipairs(dKc)do
table.insert(hKc,kKc.uuid)
table.insert(iKc,V.name(kKc.unit_id))
end
P.simTeam.dg={uuids=hKc,names=iKc,won=true,wave=xJc.total,better=true,cur={won=true,wave=xJc.total},at=os.time(),label=obf[4888],seed=tostring(jJc.r._r),style=aKc.style}
local lKc=string.format(obf[4889],table.concat(iKc,obf[2763]),fKc/60,eKc/60)
F.log(1,obf[4562],string.format(obf[4890],jJc.d,lKc))
pcall(function()
local mKc,nKc=pcall(jb.roomName,jJc)
gb.explainSave(obf[3427],string.format(obf[4891],jJc.d,mKc and tostring(nKc)or obf[2892]),xJc,dKc,{lKc..obf[4892]},true,pJc,{won=true,wave=xJc.total,total=xJc.total,steps=gKc.wins,mySteps=aKc.wins,realW=gKc.w,realL=gKc.l})
end)
if lJc then
if not ib.same(ib.team(),hKc)then
jb.startTeam(hKc,jJc,obf[4893]..jJc.d)
end
elseif O.autoTeam then
ab.equipTeam(hKc,obf[4893]..jJc.d)
task.wait(0.5)
else
F.log(1,obf[4562],obf[4894])
end
return
end
end
end
if aKc.wins>=3* #gb.LADDER and aKc.lostHere==0 then
gb.memo=nil
local oKc,pKc={},{}
for qKc,rKc in ipairs(pJc)do
table.insert(oKc,rKc.uuid)
table.insert(pKc,V.name(rKc.unit_id))
end
P.simTeam.dg={uuids=oKc,names=pKc,won=true,wave=xJc.total,better=false,cur={won=true,wave=xJc.total},at=os.time(),label=obf[4888],seed=tostring(jJc.r._r),style=aKc.style}
F.log(1,obf[4562],string.format(obf[4895],jJc.d,gb.LADDER[#gb.LADDER],aKc.w,aKc.l))
pcall(function()
local sKc,tKc=pcall(jb.roomName,jJc)
gb.explainSave(obf[3427],string.format(obf[4891],jJc.d,sKc and tostring(tKc)or obf[2892]),xJc,pJc,{string.format(obf[4896],gb.LADDER[#gb.LADDER],aKc.w,aKc.l)},false,pJc,{won=true,wave=xJc.total,total=xJc.total,steps=aKc.wins,mySteps=aKc.wins,realW=aKc.w,realL=aKc.l})
end)
if lJc and type(P.savedTeam)==obf[2639]and not ib.same(ib.team(),P.savedTeam)then
jb.startTeam(P.savedTeam,jJc,obf[4897]..jJc.d,true)
end
return
end
local uKc=gb.pool(wJc,xJc)
local vKc=(jb.lives(kJc)<=1 and 45 or 20)/ #zJc
local wKc,xKc,yKc,zKc
for AKc,BKc in ipairs(zJc)do
local CKc,DKc,EKc,FKc=gb.bestTeam(BKc.info,pJc,uKc,vKc)
local GKc=BJc(CKc,BKc)
if SJc(GKc,zKc)then
wKc,xKc,yKc,zKc=CKc,DKc,FKc,GKc
end
end
local HKc=gb.sig(wKc)==gb.sig(pJc)
if HKc then
zKc=aKc
end
if HKc and aKc.lostHere>=1 then
pcall(function()
local IKc,JKc=gb.lockIds(),{}
for KKc,LKc in ipairs(pJc)do
local MKc,NKc=pcall(V.score,LKc,xJc.mod)
JKc[KKc]={farm=V.isFarm(LKc.unit_id),buff=V.allyBuff(LKc.unit_id)and true or false,kept=IKc[LKc.unit_id]==true,score=MKc and tonumber(NKc)or 0}
end
local OKc=jb.weakSlot(JKc)
if not OKc then
return
end
local PKc,QKc,RKc=0,nil,nil
for SKc,TKc in ipairs(uKc)do
if PKc>=5 then
break
end
local UKc=V.isFarm(TKc.unit_id)
for VKc,WKc in ipairs(pJc)do
if VKc~=OKc and V.sameGroup(WKc.unit_id,TKc.unit_id)then
UKc=true
end
end
if not UKc and TKc.unit_id~=pJc[OKc].unit_id then
PKc=PKc+1
local XKc=table.clone(pJc)
XKc[OKc]=TKc
local YKc=BJc(XKc,OJc(aKc.style))
if not RKc or YKc.score>RKc.score then
QKc,RKc=XKc,YKc
end
task.wait()
end
end
if QKc and jb.lostSwap(aKc,RKc,false)then
F.log(1,obf[4562],string.format(obf[4898],jJc.d,aKc.lostHere,aKc.lostHere==1 and obf[1555]or obf[2483],V.name(QKc[OKc].unit_id),V.name(pJc[OKc].unit_id)))
wKc,zKc,HKc=QKc,RKc,false
xKc={won=RKc.wins>0,wave=RKc.reach}
end
end)
end
if(xJc.regen or 0)>0 then
local ZKc=false
for _Kc,aLc in ipairs(pJc)do
if V.bleeds(aLc.unit_id)then
ZKc=true
end
end
for bLc,cLc in ipairs(wKc)do
if V.bleeds(cLc.unit_id)then
ZKc=true
end
end
local dLc=not ZKc and V.bestBleeder(pJc)or nil
if dLc then
local eLc={}
for fLc,gLc in ipairs(pJc)do
if not V.isFarm(gLc.unit_id)and not V.allyBuff(gLc.unit_id)then
local hLc=table.clone(pJc)
hLc[fLc]=dLc
local iLc=BJc(hLc,OJc(zKc.style))
table.insert(eLc,string.format(obf[4899],V.name(gLc.unit_id),iLc.wins))
if iLc.score>zKc.score then
wKc,zKc,HKc=hLc,iLc,false
xKc={won=iLc.wins>0,wave=iLc.reach}
end
task.wait()
end
end
F.log(1,obf[4562],string.format(obf[4900],jJc.d,V.name(dLc.unit_id),V.bleeds(dLc.unit_id)or 0,table.concat(eLc,obf[3032])))
jb.bleedTried=string.format(obf[4901],V.name(dLc.unit_id),V.bleeds(dLc.unit_id)or 0,table.concat(eLc,obf[3032]))
end
end
gb.memo=nil
local jLc=zKc.wins>aKc.wins or(zKc.wins==aKc.wins and(zKc.far or 0)>(aKc.far or 0))
local kLc=not HKc and jLc and zKc.lostHere<=aKc.lostHere
local lLc
if not kLc and jb.lostSwap(aKc,zKc,HKc)then
kLc,jLc=true,true
lLc=string.format(obf[4902],aKc.lostHere,aKc.lostHere==1 and obf[1555]or obf[2483])
F.log(1,obf[4562],string.format(obf[4903],jJc.d,lLc))
end
if not kLc and not HKc then
local mLc,nLc=pcall(jb.missCounter,xJc,pJc,wKc)
if mLc and nLc then
kLc,jLc=true,true
lLc=nLc
F.log(1,obf[4562],string.format(obf[4903],jJc.d,nLc))
end
end
local oLc
if O.dgFaster and not kLc and not HKc and zKc.wins==aKc.wins and aKc.wins>0 and zKc.lostHere<=aKc.lostHere then
pcall(function()
local pLc=OJc(zKc.style).info
local qLc=gb.run(pLc,gb.teamFrom(pJc,pLc.map),{hpMul=1})
local rLc=gb.run(pLc,gb.teamFrom(wKc,pLc.map),{hpMul=1})
local sLc,tLc=qLc and qLc.won and tonumber(qLc.t),rLc and rLc.won and tonumber(rLc.t)
if sLc and tLc and tLc<=sLc*(1-gb.TEAM_FASTER)and sLc-tLc>=gb.TEAM_FASTER_S then
kLc,jLc=true,true
oLc=string.format(obf[4904],tLc/60,sLc/60)
F.log(1,obf[4562],string.format(obf[4903],jJc.d,oLc))
end
end)
end
local uLc,vLc={},{}
for wLc,xLc in ipairs(wKc)do
table.insert(uLc,xLc.uuid)
table.insert(vLc,V.name(xLc.unit_id))
end
P.simTeam.dg={uuids=uLc,names=vLc,won=xKc.won,wave=xKc.wave,better=kLc,cur={won=yKc.won,wave=yKc.wave},at=os.time(),label=obf[4888],seed=tostring(jJc.r._r),style=(kLc and zKc.style)or aKc.style}
local function yLc(zLc)
return string.format(obf[4905],zLc.wins,jb.WAY_WORDS[zLc.style]or obf[1555],math.floor(zLc.reach+0.5),zLc.w,zLc.l)
end
pcall(function()
local ALc={string.format(obf[4906],#uKc)}
if jb.bleedTried then
table.insert(ALc,jb.bleedTried)
end
jb.bleedTried=nil
local function BLc(CLc)
return string.format(obf[4907],CLc.wins,3* #gb.LADDER,jb.WAY_WORDS[CLc.style]or obf[1555],CLc.w,CLc.l,(CLc.lostHere or 0)>0 and string.format(obf[4908],CLc.lostHere,(CLc.left or 0)>0 and string.format(obf[4909],CLc.left)or obf[1555])or obf[1555])
end
if HKc and aKc.wins>=3* #gb.LADDER then
table.insert(ALc,string.format(obf[4910],gb.LADDER[#gb.LADDER],aKc.w,aKc.l))
elseif HKc then
table.insert(ALc,obf[4911]..BLc(aKc))
else
table.insert(ALc,obf[4912]..BLc(zKc))
table.insert(ALc,obf[4913]..BLc(aKc))
if kLc and lLc then
table.insert(ALc,lLc)
elseif kLc and oLc then
table.insert(ALc,oLc)
elseif kLc then
table.insert(ALc,obf[4914])
elseif not jLc then
table.insert(ALc,obf[4915])
else
table.insert(ALc,string.format(obf[4916],zKc.lostHere))
end
end
local DLc,ELc=pcall(jb.roomName,jJc)
local FLc=kLc and zKc or aKc
gb.explainSave(obf[3427],string.format(obf[4891],jJc.d,DLc and tostring(ELc)or obf[2892]),xJc,kLc and wKc or pJc,ALc,kLc,pJc,{won=kLc and xKc.won or yKc.won,wave=kLc and xKc.wave or yKc.wave,total=xJc.total,steps=FLc.wins,mySteps=aKc.wins,realW=FLc.w,realL=FLc.l})
end)
if not kLc then
if HKc and aKc.wins>=3* #gb.LADDER then
F.log(1,obf[4562],string.format(obf[4917],jJc.d,#uKc,gb.LADDER[#gb.LADDER],aKc.w,aKc.l))
elseif HKc then
F.log(1,obf[4562],string.format(obf[4918],jJc.d,#uKc,yLc(aKc)))
elseif not jLc then
F.log(1,obf[4562],string.format(obf[4919],jJc.d,yLc(aKc),table.concat(vLc,obf[2763]),yLc(zKc)))
else
