function bb.buildPath()
bb.samples={}
local TNc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not TNc then
return
end
for UNc,VNc in pairs(TNc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[UNc.Name])then
local WNc={}
for XNc,YNc in ipairs(VNc.points or{})do
table.insert(WNc,YNc.part.Position)
end
local ZNc=0
for _Nc=2,#WNc do
ZNc=ZNc+(WNc[_Nc]-WNc[_Nc-1]).Magnitude
end
local aOc=0
for bOc=2,#WNc do
local cOc,dOc=WNc[bOc-1],WNc[bOc]
local eOc=(dOc-cOc).Magnitude
local fOc=math.max(1,math.floor(eOc/2))
for gOc=0,fOc-1 do
local hOc=cOc:Lerp(dOc,gOc/fOc)
table.insert(bb.samples,{pos=hOc,prog=(aOc+eOc*gOc/fOc)/math.max(1,ZNc),lane=UNc.Name})
end
aOc=aOc+eOc
end
if WNc[#WNc]then
table.insert(bb.samples,{pos=WNc[#WNc],prog=1,lane=UNc.Name})
end
end
end
pcall(bb.readHidden,TNc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local iOc=tonumber(bb.ld and bb.ld._portal_lanes)
local jOc=gb.laneList(bb.samples)
if iOc and iOc>=1 and jOc and#jOc>iOc then
bb.laneWant=iOc
end
bb.laneTotal=jOc and#jOc or 1
bb.countLanes()
end
function bb.readHidden(kOc)
local lOc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(lOc)~=obf[2639]or not next(lOc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local mOc
for nOc,oOc in pairs(kOc)do
if lOc[nOc.Name]and type(oOc.points)==obf[2639]and#oOc.points>=2 then
local pOc={}
for qOc,rOc in ipairs(oOc.points)do
pOc[qOc]=U.flat(rOc.part.Position)
end
local sOc={}
for tOc,uOc in ipairs(bb.samples)do
local vOc=tostring(uOc.lane)
sOc[vOc]=sOc[vOc]or{}
table.insert(sOc[vOc],uOc)
end
local wOc,xOc
for yOc,zOc in pairs(sOc)do
local AOc=0
for BOc=1,#pOc,math.max(1,math.floor(#pOc/20))do
local COc=math.huge
for DOc,EOc in ipairs(zOc)do
local FOc=(U.flat(EOc.pos)-pOc[BOc]).Magnitude
if FOc<COc then
COc=FOc
end
end
AOc=AOc+COc
end
if not xOc or AOc<xOc then
wOc,xOc=yOc,AOc
end
end
local GOc,HOc,IOc,JOc,KOc,LOc={},nil,nil,nil,0,0
for MOc,NOc in ipairs(pOc)do
local OOc,POc=nil,math.huge
for QOc,ROc in ipairs(sOc[wOc])do
local SOc=(U.flat(ROc.pos)-NOc).Magnitude
if SOc<POc then
POc,OOc=SOc,ROc.prog
end
end
LOc=math.max(LOc,POc)
if IOc then
local TOc=OOc-IOc
local UOc=(TOc>0.002 and 1)or(TOc< -0.002 and-1)or JOc
if JOc and UOc and UOc~=JOc then
table.insert(GOc,math.floor(IOc*1000+0.5)/1000)
end
JOc,KOc=UOc or JOc,KOc+math.abs(TOc)
else
HOc=OOc
end
IOc=OOc
if MOc%50==0 then
task.wait()
end
end
if IOc and LOc<=8 then
table.insert(GOc,math.floor(IOc*1000+0.5)/1000)
mOc=mOc or{}
mOc[nOc.Name]={from=math.floor((HOc or 0)*1000+0.5)/1000,len=math.floor(KOc*1000+0.5)/1000,turns=GOc,road=wOc}
end
end
end
if not mOc then
return
end
local VOc=bb.ld.map
P.maps[VOc]=P.maps[VOc]or{}
local WOc=P.maps[VOc].hidden
P.maps[VOc].hidden=mOc
if type(WOc)~=obf[2639]then
for XOc,YOc in pairs(mOc)do
F.log(1,obf[3343],string.format(obf[4969],XOc,YOc.len,tostring(YOc.road),math.floor((#YOc.turns-1)/2)))
end
F.saveSoon()
end
end
function bb.countLanes()
local ZOc,_Oc,aPc={},0,0
for bPc,cPc in ipairs(bb.samples)do
local dPc=tostring(cPc.lane)
if not ZOc[dPc]then
_Oc=_Oc+1
end
ZOc[dPc]=(ZOc[dPc]or 0)+1
aPc=aPc+1
end
bb.laneCount={n=_Oc,by=ZOc,avg=_Oc>0 and aPc/_Oc or 1}
if _Oc>=2 then
