function bb.coverage(XSc,YSc)
local ZSc={}
for _Sc,aTc in ipairs(XSc)do
local bTc=aTc._stats
if not V.isFarm(bTc.id.Value)and bTc:FindFirstChild(obf[2909])then
table.insert(ZSc,{p=U.flat(aTc:GetPivot().Position),r=bTc.range.Value*(V.SUMMONER[bTc.id.Value]and V.SUMMONER[bTc.id.Value].reach or 1),air=bb.canAir(aTc)})
end
end
local cTc,dTc=0,0
if#ZSc>0 then
for eTc,fTc in ipairs(bb.samples)do
if fTc.prog>dTc then
local gTc=U.flat(fTc.pos)
for hTc,iTc in ipairs(ZSc)do
if(gTc-iTc.p).Magnitude<=iTc.r then
if fTc.prog>cTc then
cTc=fTc.prog
end
if iTc.air then
dTc=fTc.prog
break
end
end
end
end
end
end
local jTc,kTc={},bb.laneCount
if kTc and kTc.n>=2 and#ZSc>0 then
local lTc={}
for mTc,nTc in ipairs(bb.samples)do
local oTc=U.flat(nTc.pos)
for pTc,qTc in ipairs(ZSc)do
if(oTc-qTc.p).Magnitude<=qTc.r then
local rTc=tostring(nTc.lane)
lTc[rTc]=(lTc[rTc]or 0)+1
if nTc.prog>(jTc[rTc]or 0)then
jTc[rTc]=nTc.prog
end
break
end
end
end
local sTc,tTc={},0
for uTc,vTc in pairs(kTc.by)do
sTc[uTc]=(lTc[uTc]or 0)/math.max(1,vTc)
tTc=math.max(tTc,sTc[uTc])
end
bb.laneW={}
for wTc,xTc in pairs(kTc.by)do
bb.laneW[wTc]=(kTc.avg/math.max(1,xTc))*(1+1.5*(tTc>0 and(1-sTc[wTc]/tTc)or 0))
