if bb._boxSig~=GTc then
local JTc={}
for KTc,LTc in ipairs(bb.samples)do
local MTc,NTc=U.flat(LTc.pos),0
for OTc,PTc in ipairs(ZSc)do
if(MTc-PTc.p).Magnitude<=PTc.r then
NTc=NTc+1
end
