function bb.validOpen(Nbd,Obd)
local Pbd=N.PC.raycast(Nbd+Vector3 .new(0,40,0),Vector3 .new(0,-120,0))
if not Pbd then
return nil
end
if not N.PC.is_valid_raycast_hit(Pbd.Instance,Obd)then
return nil
end
local Qbd=Pbd.Position
if bb.blockedSpot(Qbd)then
return nil
end
local Rbd=(tonumber(Obd.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(Rbd*2,2.5,Rbd*2)
bb.probe.CFrame=CFrame.new(Qbd+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
return Qbd
end
