bb.BARR_DENSE=0.75
bb.BARR_TEAM,bb.BARR_WAVE=1,1
bb.BARR_GAP=0.1
function bb.barricadeOrder(bkd,ckd)
local dkd,ekd={},0
for fkd,gkd in ipairs(bkd or{})do
local hkd=Vector3 .new(gkd.pos.X,0,gkd.pos.Z)
local ikd,jkd=0,math.huge
for kkd,lkd in ipairs(ckd or{})do
local mkd=(lkd.p-hkd).Magnitude
if mkd<=lkd.r then
ikd=ikd+1
end
if mkd<jkd then
jkd=mkd
end
end
if ikd>ekd then
ekd=ikd
end
table.insert(dkd,{s=gkd,n=ikd,d=jkd})
end
if ekd<1 then
return{}
end
local nkd=ekd>=2
local okd,pkd={},{}
for qkd,rkd in ipairs(dkd)do
if(nkd and rkd.n>=ekd*bb.BARR_DENSE)or(not nkd and rkd.n>=1)then
local skd=tostring(rkd.s.lane)
if not okd[skd]then
okd[skd]={}
table.insert(pkd,skd)
end
table.insert(okd[skd],rkd)
end
end
table.sort(pkd)
local tkd=0
for ukd,vkd in ipairs(pkd)do
local wkd=okd[vkd]
if not nkd then
table.sort(wkd,function(xkd,ykd)
return(xkd.s.prog or 0)<(ykd.s.prog or 0)
end)
for zkd=2,#wkd do
if(wkd[zkd].s.prog or 0)-(wkd[zkd-1].s.prog or 0)>bb.BARR_GAP then
for Akd= #wkd,zkd,-1 do
table.remove(wkd,Akd)
end
break
end
end
table.sort(wkd,function(Bkd,Ckd)
if Bkd.d~=Ckd.d then
return Bkd.d<Ckd.d
end
return(Bkd.s.prog or 0)>(Ckd.s.prog or 0)
end)
else
table.sort(wkd,function(Dkd,Ekd)
if Dkd.n~=Ekd.n then
return Dkd.n>Ekd.n
end
return(Dkd.s.prog or 0)>(Ekd.s.prog or 0)
end)
end
tkd=math.max(tkd,#wkd)
end
local Fkd={}
for Gkd=1,tkd do
for Hkd,Ikd in ipairs(pkd)do
if okd[Ikd][Gkd]then
table.insert(Fkd,okd[Ikd][Gkd].s.pos)
end
end
end
return Fkd
end
function bb.defPick(Jkd,Kkd,Lkd,Mkd,Nkd,Okd,Pkd)
