if Jkd==obf[2841]or Jkd==obf[5205]then
local Rkd={}
local Skd={}
if Jkd==obf[5205]then
for Tkd,Ukd in ipairs(Nkd or{})do
local Vkd=U.flat(Ukd.pos)
for Wkd,Xkd in ipairs(Lkd)do
if(Xkd.p-Vkd).Magnitude<=Xkd.r then
table.insert(Skd,Vkd)
break
end
end
end
end
for Ykd,Zkd in ipairs(Mkd)do
local _kd=U.flat(Zkd)
local ald,bld,cld=0,0,false
for dld,eld in ipairs(Lkd)do
local fld=(eld.p-_kd).Magnitude
if fld<=Kkd then
ald=ald+1
bld=bld+fld
end
if Pkd and fld<=Pkd then
cld=true
end
end
local gld=0
for hld,ild in ipairs(Skd)do
if(ild-_kd).Magnitude<=Kkd then
gld=gld+1
end
end
local jld=Jkd==obf[2841]and(ald*1000-bld-(cld and 500 or 0))or(gld*1000+Okd(Zkd,Kkd)*10+ald)
if Jkd~=obf[2841]or ald>0 then
table.insert(Rkd,{p=Zkd,sc=jld})
end
end
table.sort(Rkd,function(kld,lld)
return kld.sc>lld.sc
end)
for mld=1,math.min(1000,#Rkd)do
Qkd[mld]=Rkd[mld].p
end
elseif Jkd==obf[5204]or Jkd==obf[5203]then
local nld={}
for pld,qld in ipairs(Nkd)do
local rld=U.flat(qld.pos)
for sld,tld in ipairs(Lkd)do
if(tld.p-rld).Magnitude<=tld.r then
table.insert(nld,qld)
break
end
end
end
if Jkd==obf[5203]then
for uld,vld in ipairs(bb.barricadeOrder(nld,Lkd))do
