return(wld.prog or 0)>(xld.prog or 0)
end)
for yld=3,math.min(#nld,120)do
table.insert(Qkd,nld[yld].pos)
end
if#Qkd==0 and nld[1]then
Qkd[1]=nld[1].pos
end
end
