function bb.atkRead(trd,urd)
local vrd,wrd=trd.t0-0.12,trd.last+0.12
local xrd,yrd={},0
for zrd,Ard in ipairs(urd)do
if Ard.t>=vrd and Ard.t<=wrd then
for Brd in pairs(Ard.changed)do
if Brd~=trd.m then
return nil,obf[5258]
end
end
for Crd,Drd in ipairs(Ard.drops)do
local Erd=xrd[Drd.m]or{n=0,pos=Drd.pos}
Erd.n=Erd.n+1
xrd[Drd.m]=Erd
yrd=yrd+Drd.d
end
end
end
local Frd={}
for Grd,Hrd in pairs(xrd)do
table.insert(Frd,Hrd)
end
if#Frd==0 then
return nil,obf[5259]
end
if yrd>trd.dealt*1.25+1 then
return nil,obf[5260]
end
if yrd<trd.dealt*0.4 and not trd.loose then
return nil,obf[5261]
end
local Ird,Jrd,Krd=0,0,1
for Lrd,Mrd in ipairs(Frd)do
Krd=math.max(Krd,Mrd.n)
Jrd=math.max(Jrd,((Mrd.pos.X-trd.pos.X)^2+(Mrd.pos.Z-trd.pos.Z)^2)^0.5/math.max(1,trd.range))
for Nrd=Lrd+1,#Frd do
Ird=math.max(Ird,((Mrd.pos.X-Frd[Nrd].pos.X)^2+(Mrd.pos.Z-Frd[Nrd].pos.Z)^2)^0.5)
end
end
return{hit= #Frd,crowd=math.max(trd.crowd,#Frd),spread=Ird,reach=Jrd,strikes=Krd}
end
function bb.atkWatch()
if bb.atkOn then
