if fsd and gsd then
table.insert(Vrd,{m=csd,hum=fsd,root=gsd})
end
elseif esd then
local hsd=dsd:FindFirstChild(obf[3035])
if hsd then
table.insert(Urd,{m=csd,td=hsd})
local isd,jsd,ksd=dsd:FindFirstChild(obf[2755]),dsd:FindFirstChild(obf[2909]),dsd:FindFirstChild(obf[3034])
if Yrd[csd]and isd and jsd and ksd and V.attackBlind(isd.Value)then
local lsd=P.atkSeen and P.atkSeen[isd.Value]
if not(type(lsd)==obf[2639]and type(lsd.h)==obf[2639]and#lsd.h>=bb.ATK_KEEP)then
local msd=dsd:FindFirstChild(obf[3092])
table.insert(Trd,{m=csd,id=ksd.Value,atk=isd.Value,range=tonumber(jsd.Value)or 0,cd=msd and tonumber(msd.Value)or 2})
end
end
end
end
end
end
if#Trd==0 and next(Srd)==nil then
Prd,Qrd,Rrd={},{},{}
task.wait(1)
else
local nsd={}
for osd,psd in ipairs(Vrd)do
local qsd,rsd=psd.hum.Health,Prd[psd.m]
if rsd and qsd<rsd-0.5 then
table.insert(nsd,{m=psd.m,d=rsd-qsd,pos=psd.root.Position})
end
Prd[psd.m]=qsd
end
local ssd={}
for tsd,usd in ipairs(Urd)do
