table.insert(Rrd,{t=Xrd,drops=nsd,changed=ssd})
while Rrd[1]and Xrd-Rrd[1].t>2.5 do
table.remove(Rrd,1)
end
for xsd,ysd in ipairs(Trd)do
local zsd=ssd[ysd.m]
if zsd then
local Asd=Srd[ysd.m]
if not Asd then
local Bsd,Csd=ysd.m:GetPivot().Position,0
for Dsd,Esd in ipairs(Vrd)do
if(Prd[Esd.m]or 0)>0 and Esd.m.Parent then
local Fsd=Esd.root.Position
if((Fsd.X-Bsd.X)^2+(Fsd.Z-Bsd.Z)^2)^0.5<=ysd.range then
Csd=Csd+1
