end
end
Asd={m=ysd.m,id=ysd.id,atk=ysd.atk,range=ysd.range,cd=ysd.cd,pos=Bsd,crowd=Csd,t0=Xrd,dealt=0}
Srd[ysd.m]=Asd
end
Asd.dealt,Asd.last=Asd.dealt+zsd,Xrd
end
end
for Gsd,Hsd in pairs(Srd)do
if Xrd-Hsd.last>math.min(0.3,Hsd.cd*0.3)+0.12 or Xrd-Hsd.t0>math.max(0.4,Hsd.cd*0.6)then
Srd[Gsd]=nil
local Isd,Jsd,Ksd=pcall(bb.atkRead,Hsd,Rrd)
bb.atkStat=bb.atkStat or{ok=0,no=0,why={}}
if Isd and Jsd then
bb.atkStat.ok=bb.atkStat.ok+1
pcall(bb.atkNote,Hsd.atk,Hsd.id,Jsd)
else
bb.atkStat.no=bb.atkStat.no+1
local Lsd=tostring(Isd and Ksd or Jsd)
bb.atkStat.why[Lsd]=(bb.atkStat.why[Lsd]or 0)+1
end
end
end
end
end
end)
end
