bb.REAL_WIN=75
function bb.realK(ztd)
local Atd=bb.realC
local Btd=U.now()
if not Atd then
Atd={t=0,k={},snaps={},seen={}}
bb.realC=Atd
end
if Btd-Atd.t>=5 then
Atd.t=Btd
Atd.k={}
local Ctd,Dtd,Etd=pcall(bb.damageShares)
local Ftd={}
if Ctd and type(Dtd)==obf[2639]and(Etd or 0)>0 then
for Gtd,Htd in pairs(Dtd)do
Ftd[Gtd]=Htd*Etd
end
end
local Itd,Jtd={},0
for Ktd,Ltd in ipairs(bb.mine or{})do
local Mtd=Ltd:FindFirstChild(obf[2711])
local Ntd=Mtd and Mtd:FindFirstChild(obf[3034])and Mtd.id.Value
if Ntd and not V.isFarm(Ntd)then
local Otd,Ptd=pcall(bb.liveDps,Ltd,Ntd)
Ptd=Otd and tonumber(Ptd)or 0
Itd[Ntd]=(Itd[Ntd]or 0)+Ptd
Jtd=Jtd+Ptd
Atd.seen[Ntd]=Atd.seen[Ntd]or Btd
end
end
table.insert(Atd.snaps,{t=Btd,abs=Ftd})
while#Atd.snaps>1 and Btd-Atd.snaps[2].t>=bb.REAL_WIN do
table.remove(Atd.snaps,1)
end
local Qtd=Atd.snaps[1]
if Btd-Qtd.t>=20 and Jtd>0 then
local Rtd,Std={},0
for Ttd in pairs(Itd)do
local Utd=math.max(0,(Ftd[Ttd]or 0)-(Qtd.abs[Ttd]or 0))
Rtd[Ttd]=Utd
Std=Std+Utd
end
if Std>0 then
local Vtd
for Wtd,Xtd in pairs(Itd)do
if Btd-Atd.seen[Wtd]>=eb.REAL_AGE then
local Ytd=eb.realK(Rtd[Wtd]/Std,Xtd/Jtd,eb.REAL_AGE)
if not Vtd or Ytd<Vtd then
Vtd=Ytd
end
end
end
for Ztd,_td in pairs(Itd)do
Atd.k[Ztd]=eb.realK(Rtd[Ztd]/Std,_td/Jtd,Btd-Atd.seen[Ztd],Vtd)
end
end
end
end
return Atd.k[ztd]or 1
end
function bb.upPath(aud,bud,cud,dud,eud,fud,gud,hud)
