for mud=cud+2,bud.max do
local nud=bud[mud]
if not nud then
break
end
lud=lud+(tonumber(nud.cost)or 0)*(eud or 1)
local oud=eb.shieldGainAhead(aud,bud[cud],fud(mud),nud,gud,hud)
if oud and oud/math.max(1,lud)>kud then
kud=oud/math.max(1,lud)
