function bb.holdGain(Gwd,Hwd)
if bb.random or not Hwd or not bb.info then
return 0
end
local Iwd=V.attackInfo(Hwd.atk,Hwd.range)
if(Iwd.stun or 0)<=0 and(Iwd.slowTime or 0)<=0 then
return 0
end
local Jwd=0
for Kwd,Lwd in ipairs(bb.mine or{})do
local Mwd=Lwd._stats
local Nwd=V.rows(Mwd.id.Value)
local Owd=Nwd and Nwd[math.min(Mwd.upgrade.Value,Nwd.max)]
local Pwd=Owd and Owd.atk and V.attackInfo(Owd.atk,Owd.range)
if Pwd and((Pwd.stun or 0)>0 or(Pwd.slowTime or 0)>0)then
Jwd=Jwd+1
end
end
local Qwd,Rwd=gb.mask(bb.info.map,V.range(Gwd.u,0)*(bb.info.rangeScale or 1)),0
for Swd=1,gb.BINS do
if Qwd[Swd]then
Rwd=Rwd+1
end
end
local Twd=bb.depth and bb.depth.units>0 and bb.depth.covEnd or 1
local Uwd=(V.airFrom(Gwd.id)==0)and 1 or(1-(1-N.FLY_GROUND)*math.min(1,bb.info.flyChance or 0))
return eb.holdGain(Iwd,bb.teamDps or 0,Rwd/(math.max(0.1,Twd)*gb.BINS)*Uwd,Jwd)
end
function bb.buffGain(Vwd)
local Wwd=V.allyBuff(Vwd.id)
if not Wwd or O.actives==false then
return 0
end
local Xwd,Ywd,Zwd=bb.buffShort(Wwd)
local _wd=V.stackCap(Wwd.attack)
local axd,bxd=pcall(V.range,Vwd.u,0)
bxd=(axd and tonumber(bxd)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local cxd=_wd and O.community and tonumber(Wwd.time)and tonumber(Zwd)
local function dxd(exd,fxd)
local gxd=math.floor(exd*Wwd.time/math.max(1,Zwd)+0.001)
return math.min(_wd,(1+fxd)^gxd-1)
end
local hxd=0
for ixd,jxd in ipairs(Xwd)do
local kxd=0
for lxd,mxd in ipairs(Xwd)do
if(mxd.pos-jxd.pos).Magnitude<=bxd then
local nxd=Wwd.types[mxd.base]
local oxd=nxd*Wwd.uptime
if cxd then
local pxd,qxd=dxd(mxd.n,nxd),mxd.n+1
while qxd<mxd.n+6 and dxd(qxd,nxd)<=pxd+0.001 do
qxd=qxd+1
end
oxd=math.max(0,(dxd(qxd,nxd)-pxd)/(qxd-mxd.n))
elseif _wd then
oxd=math.max(0,math.min(_wd,(mxd.n+1)*nxd*Wwd.uptime)-math.min(_wd,mxd.n*nxd*Wwd.uptime))
end
kxd=kxd+mxd.dps*oxd
end
end
hxd=math.max(hxd,kxd)
end
return hxd*(cxd and 1 or 0.7)
end
function bb.buffWanted(rxd)
