function bb.learn()
local HNd=bb.calRun and bb.calRun.potBy
if type(HNd)~=obf[2639]then
return
end
pcall(bb.sampleHelpers,true)
local INd={}
for JNd,KNd in pairs(bb.ownDealt or{})do
if not V.isFarm(KNd.id)then
INd[KNd.id]=(INd[KNd.id]or 0)+(tonumber(KNd.v)or 0)
end
end
for LNd,MNd in pairs(bb.helperDealt or{})do
if MNd.owner and V.SUMMONER[MNd.owner]and not V.droneHelper(MNd)then
INd[MNd.owner]=(INd[MNd.owner]or 0)+(tonumber(MNd.v)or 0)
end
end
local NNd=type(bb.calRun.potExp)==obf[2639]and bb.calRun.potExp or{}
local ONd,PNd=0,0
local QNd={}
for RNd,SNd in pairs(HNd)do
if SNd>0 then
ONd,PNd=ONd+(INd[RNd]or 0),PNd+SNd
local TNd=tonumber(NNd[RNd])or SNd
if TNd>0 then
table.insert(QNd,{id=RNd,r=(INd[RNd]or 0)/TNd,w=TNd})
end
end
end
if ONd<=0 or PNd<=0 then
return
end
table.sort(QNd,function(UNd,VNd)
return UNd.r<VNd.r
end)
local function WNd(XNd)
local YNd,ZNd=0,0
for _Nd,aOd in ipairs(QNd)do
if aOd.id~=XNd then
YNd=YNd+aOd.w
end
end
if YNd<=0 then
return nil
end
for bOd,cOd in ipairs(QNd)do
if cOd.id~=XNd then
ZNd=ZNd+cOd.w
if ZNd>=YNd/2 then
return cOd.r
end
end
end
end
bb.lastEff={}
for dOd,eOd in pairs(HNd)do
local fOd=WNd(dOd)
if eOd>0 and eOd/PNd>0.02 and fOd and fOd>0 then
local gOd=P.learn[dOd]or{eff=1,n=0,v=6}
V.learnUp(dOd,gOd)
local hOd=math.max(0.02,0.25*math.sqrt(30/(30+gOd.n)))
local iOd=U.clamp(((INd[dOd]or 0)/eOd)/fOd,0.2,6)
bb.lastEff[dOd]=math.floor(iOd*1000+0.5)/1000
gOd.eff=gOd.eff+(iOd-gOd.eff)*hOd
gOd.n=gOd.n+1
P.learn[dOd]=gOd
end
end
local jOd=V.mapKey((bb.info and bb.info.map)or(bb.ld and bb.ld.map),(bb.info and bb.info.mapSig)or V.mapSig(bb.ld))
if jOd and next(bb.lastEff)then
P.mapLearn=type(P.mapLearn)==obf[2639]and P.mapLearn or{}
local kOd=type(P.mapLearn[jOd])==obf[2639]and P.mapLearn[jOd]or{}
for lOd,mOd in pairs(bb.lastEff)do
local nOd=type(kOd[lOd])==obf[2639]and kOd[lOd]or{eff=mOd,n=0,v=6}
if(tonumber(nOd.v)or 0)<4 then
nOd.eff,nOd.v=(tonumber(nOd.eff)or mOd)*V.secRescale(lOd),4
end
if(tonumber(nOd.v)or 0)<5 then
nOd.eff,nOd.v=(tonumber(nOd.eff)or mOd)*(V.sumRescale(lOd)or 1),5
end
if(tonumber(nOd.v)or 0)<6 then
nOd.eff,nOd.v=(tonumber(nOd.eff)or mOd)*(1-(V.SUMMONER[lOd]and V.SUMMONER[lOd].droneShare or 0)),6
end
local oOd=math.max(0.1,0.5*math.sqrt(4/(4+(tonumber(nOd.n)or 0))))
nOd.eff=(tonumber(nOd.n)or 0)==0 and mOd or((tonumber(nOd.eff)or mOd)+(mOd-(tonumber(nOd.eff)or mOd))*oOd)
nOd.n=(tonumber(nOd.n)or 0)+1
kOd[lOd]=nOd
end
kOd._at=os.time()
P.mapLearn[jOd]=kOd
if U.count(P.mapLearn)>80 then
local pOd,qOd
for rOd,sOd in pairs(P.mapLearn)do
if not qOd or(tonumber(sOd._at)or 0)<qOd then
pOd,qOd=rOd,tonumber(sOd._at)or 0
end
end
P.mapLearn[pOd]=nil
end
end
end
function bb.randomTeam()
