function bb.baseVerdict(NUd,OUd)
local PUd=(OUd.t or 0)-(NUd.t or 0)
if PUd<bb.BASE_WIN-1 then
return false
end
local QUd=((tonumber(NUd.base)or 0)-(tonumber(OUd.base)or 0))/PUd
if QUd<=0 or(tonumber(OUd.base)or 0)<=0 then
return false
end
local RUd=OUd.base/QUd
local SUd,TUd=0,0
local UUd,VUd=NUd.foes or{},OUd.foes or{}
for WUd,XUd in pairs(VUd)do
if XUd.prog>=bb.BASE_END then
SUd=SUd+XUd.hp
local YUd=UUd[WUd]
if YUd then
TUd=TUd+math.max(0,YUd.hp-XUd.hp)
end
end
end
for ZUd,_Ud in pairs(UUd)do
if _Ud.prog>=bb.BASE_END and not VUd[ZUd]then
TUd=TUd+_Ud.hp
end
end
if SUd<=0 then
return false
end
local aVd=TUd/PUd
local bVd=aVd>0 and SUd/aVd or math.huge
local cVd={baseTime=RUd,loss=QUd,atEnd=SUd,rate=aVd,killTime=bVd}
return RUd<bb.BASE_SOON and bVd>RUd*bb.BASE_MARGIN,cVd
end
